import pandas as pd
import numpy as np
import json
from scipy import stats as scipy_stats

df = pd.read_csv('/data/df.csv')

result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

try:
    df_prod = df[df['row_kind'].isin(['sale', 'non_product', 'other_currency']) == False].copy()
    df_prod = df[~df['row_kind'].isin(['test', 'cancel'])].copy()
except Exception:
    df_prod = df.copy()

try:
    oee_by_line = (
        df_prod.groupby('Line')
        .apply(lambda g: (g['Ideal Cycle Time (s)'] * g['Good Count']).sum() / 60.0 / g['Planned Minutes'].sum())
        .reset_index()
    )
    oee_by_line.columns = ['Line', 'oee']

    oee_results = [{"name": str(row['Line']), "value": round(float(row['oee']), 6)} for _, row in oee_by_line.iterrows()]

    result['segments'].append({
        "segment_column": "Line",
        "metric_column": "Good Count",
        "aggregation": "ratio",
        "label": "oee",
        "results": oee_results
    })
except Exception as e:
    result['segments'].append({
        "segment_column": "Line",
        "metric_column": "Good Count",
        "aggregation": "ratio",
        "label": "oee",
        "results": [{"name": "error", "value": 0.0}]
    })

try:
    overall_oee = (df_prod['Ideal Cycle Time (s)'] * df_prod['Good Count']).sum() / 60.0 / df_prod['Planned Minutes'].sum()
    result['segments'].append({
        "segment_column": "Line",
        "metric_column": "Good Count",
        "aggregation": "ratio",
        "label": "oee_overall",
        "results": [{"name": "overall", "value": round(float(overall_oee), 6)}]
    })
except Exception:
    pass

try:
    gc_by_line = (
        df_prod.groupby('Line')['Good Count'].sum().reset_index()
    )
    gc_results = [{"name": str(row['Line']), "value": float(row['Good Count'])} for _, row in gc_by_line.iterrows()]
    result['segments'].append({
        "segment_column": "Line",
        "metric_column": "Good Count",
        "aggregation": "sum",
        "label": None,
        "results": gc_results
    })
except Exception:
    pass

try:
    pm_by_line = (
        df_prod.groupby('Line')['Planned Minutes'].sum().reset_index()
    )
    pm_results = [{"name": str(row['Line']), "value": float(row['Planned Minutes'])} for _, row in pm_by_line.iterrows()]
    result['segments'].append({
        "segment_column": "Line",
        "metric_column": "Planned Minutes",
        "aggregation": "sum",
        "label": None,
        "results": pm_results
    })
except Exception:
    pass

result['assumptions'] = [
    "OEE = sum(Ideal Cycle Time (s) * Good Count) / 60 / sum(Planned Minutes) per line, pooled over all shifts.",
    "Rows with row_kind 'test' or 'cancel' excluded from OEE computation.",
    "Ideal Cycle Time (s) used per-row as given; 1 flagged kpi_over_max row included unless excluded by row_kind filter.",
    "Run time not needed for OEE formula used here (performance * quality * availability collapsed into single formula).",
    "OEE values are fractions (e.g. 0.75 = 75%)."
]

