}

try:
    cm_types = [
        'cm','em','corrective','corrective maintenance','emergency',
        'emergency maintenance','emergency repair','breakdown',
        'breakdown maintenance','breakdown repair','reactive',
        'reactive maintenance','unplanned','unplanned maintenance',
        'unplanned breakdown','repair','fault','failure'
    ]

    cancelled_statuses = ['can','cancel','cancelled','canceled','void','voided','rejected']

    df_active = df[~df['row_kind'].str.lower().isin(['cancel']) &
                   ~df['STATUS'].str.lower().isin(cancelled_statuses)].copy()

    df_cm = df_active[
        df_active['WORKTYPE'].str.lower().isin(cm_types) &
        df_active['repair_hours'].notna() &
        (df_active['repair_hours'] >= 0)
    ].copy()

    overall_mttr = df_cm['repair_hours'].sum() / df_cm['WONUM'].nunique() if df_cm['WONUM'].nunique() > 0 else 0.0

    result['segments'].append({
        "segment_column": "WORKTYPE",
        "metric_column": "repair_hours",
        "aggregation": "ratio",
        "label": "mttr_hours",
        "results": [{"name": "all_corrective_em", "value": round(float(overall_mttr), 4)}]
    })

    wt_groups = []
    for wt, grp in df_cm.groupby('WORKTYPE'):
        n_wo = grp['WONUM'].nunique()
        if n_wo > 0:
            mttr_wt = grp['repair_hours'].sum() / n_wo
            wt_groups.append({"name": str(wt), "value": round(float(mttr_wt), 4)})

    result['segments'].append({
        "segment_column": "WORKTYPE",
        "metric_column": "repair_hours",
        "aggregation": "ratio",
        "label": "mttr_by_worktype",
        "results": wt_groups
    })

    asset_groups = []
    for asset, grp in df_cm.groupby('ASSETNUM'):
        n_wo = grp['WONUM'].nunique()
        if n_wo > 0:
            mttr_a = grp['repair_hours'].sum() / n_wo
            asset_groups.append({"name": str(asset), "value": round(float(mttr_a), 4)})
    asset_groups_sorted = sorted(asset_groups, key=lambda x: x['value'], reverse=True)[:10]

    result['segments'].append({
        "segment_column": "ASSETNUM",
        "metric_column": "repair_hours",
        "aggregation": "ratio",
        "label": "mttr_by_asset",
        "results": asset_groups_sorted
    })

    fc_groups = []
    for fc, grp in df_cm.groupby('FAILURECODE'):
        n_wo = grp['WONUM'].nunique()
        if n_wo > 0:
            mttr_fc = grp['repair_hours'].sum() / n_wo
            fc_groups.append({"name": str(fc), "value": round(float(mttr_fc), 4)})
    fc_groups_sorted = sorted(fc_groups, key=lambda x: x['value'], reverse=True)[:10]

    result['segments'].append({
        "segment_column": "FAILURECODE",
        "metric_column": "repair_hours",
        "aggregation": "ratio",
        "label": "mttr_by_failurecode",
        "results": fc_groups_sorted
    })

    n_cm_wo = int(df_cm['WONUM'].nunique())
    n_cm_rows = int(len(df_cm))
    result['assumptions'].append(
        f"MTTR computed on {n_cm_wo} distinct corrective/EM work orders ({n_cm_rows} rows); cancelled and out-of-range repair_hours excluded."
    )
    result['assumptions'].append(
        "repair_hours column used as-is (actual_start to actual_finish); no recomputation."
    )
    result['assumptions'].append(
        f"Overall MTTR = {overall_mttr:.4f} hours across all corrective/EM work types."
    )

