try:
    df_prod['run_minutes'] = (
        df_prod['Planned Minutes']
        - df_prod['Unplanned Downtime (min)']
        - df_prod['Changeover (min)']
    )

    avail_by_shift = (
        df_prod.groupby('Shift')[['run_minutes', 'Planned Minutes']]
        .sum()
        .reset_index()
    )
    avail_by_shift['availability'] = (
        avail_by_shift['run_minutes'] / avail_by_shift['Planned Minutes']
    )
    avail_by_shift['availability'] = avail_by_shift['availability'].fillna(0.0)

    avail_results = [
        {"name": str(row['Shift']), "value": round(float(row['availability']), 6)}
        for _, row in avail_by_shift.iterrows()
    ]

    result['segments'].append({
        "segment_column": "Shift",
        "metric_column": "Planned Minutes",
        "aggregation": "ratio",
        "label": "availability",
        "results": avail_results
    })

    total_run = df_prod['run_minutes'].sum()
    total_planned = df_prod['Planned Minutes'].sum()
    overall_avail = float(total_run / total_planned) if total_planned > 0 else 0.0

    result['segments'].append({
        "segment_column": "Shift",
        "metric_column": "Planned Minutes",
        "aggregation": "ratio",
        "label": "availability_overall",
        "results": [{"name": "overall", "value": round(overall_avail, 6)}]
    })

    result['assumptions'].append(
        "Availability = (Planned - Unplanned Downtime - Changeover) / Planned, pooled per shift (not mean of ratios)."
    )
    result['assumptions'].append(
        "Rows with row_kind 'test' or 'cancel' excluded from availability calculation."
    )
    result['assumptions'].append(
        "Rows where Planned Minutes = 0 contribute 0 run time and 0 planned time to the pool."
    )

except Exception as e:
